True from collections import Counter

def transform(grid):
    points = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 2]
    if not points:
        return [row[:] for row in grid]
    row_counts = Counter(r for r, _ in points)
    col_counts = Counter(c for _, c in points)
    best_row, row_n = row_counts.most_common(1)[0]
    best_col, col_n = col_counts.most_common(1)[0]
    out = [row[:] for row in grid]
    if row_n >= col_n:
        axis = best_row
        for r, c in points:
            for rr in range(min(r, axis), max(r, axis) + 1):
                if out[rr][c] == 0:
                    out[rr][c] = 3
        for c in range(min(c for _, c in points), max(c for _, c in points) + 1):
            if out[axis][c] == 0:
                out[axis][c] = 3
    else:
        axis = best_col
        for r, c in points:
            for cc in range(min(c, axis), max(c, axis) + 1):
                if out[r][cc] == 0:
                    out[r][cc] = 3
        for r in range(min(r for r, _ in points), max(r for r, _ in points) + 1):
            if out[r][axis] == 0:
                out[r][axis] = 3
    return out
